Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- CalculateTotal: DataRow for simple inline cases ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00, DisplayName = "Single item")]
    [DataRow(5, 20.00, 100.00, DisplayName = "Multiple items")]
    [DataRow(0, 15.00, 0.00, DisplayName = "Zero quantity")]
    [DataRow(3, 0.00, 0.00, DisplayName = "Zero price")]
    [DataRow(2, 9.99, 19.98, DisplayName = "Fractional price")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- ApplyDiscount: DynamicData with ValueTuples for complex/decimal data ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (99.99m, 50, 49.995m),
    ];

    // --- ApplyDiscount: invalid inputs throw ---

    [TestMethod]
    [DataRow(-1)]
    [DataRow(101)]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(int percent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, percent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    [TestMethod]
    public void ApplyDiscount_NegativePrice_ThrowsArgumentOutOfRange()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(-10m, 5));

        Assert.AreEqual("price", ex.ParamName);
    }
}
```

**Key patterns used:**

| Technique | When |
|-----------|------|
| `[DataRow]` | Simple inline primitive values |
| `[DynamicData]` with ValueTuples | Complex types or precise `decimal` literals (`DataRow` doesn't support `decimal`) |
| `Assert.ThrowsExactly<T>` | Exception testing (replaces `[ExpectedException]`) |
| `sealed` class | Performance best practice |
| Constructor init | Enables `readonly` fields |

**Notes:**
- `DataRow` can't use `decimal` literals directly (they aren't compile-time constants), so use `DynamicData` for decimal-heavy scenarios or cast from `double` for simple cases.
- Adjust method signatures (`CalculateTotal(int, decimal)`, `ApplyDiscount(decimal, int)`) to match your actual API.
